with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , GENRAL_REMARKS as NOTE_TEXT
        , cast(null as varchar) as FOLLOW_UP_REQUIRED_INDICATOR
        , 'BJAZ_HM_BILL_DETAIL' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_bill_detail') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , ORPHAN_CLOSE_REMARK as NOTE_TEXT
        , ORPHAN_FOLLOW_FLAG as FOLLOW_UP_REQUIRED_INDICATOR
        , 'BJAZ_HM_ORPHAN_REG' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_orphan_reg') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , QUERY_REMARK as NOTE_TEXT
        , cast(null as varchar) as FOLLOW_UP_REQUIRED_INDICATOR
        , 'BJAZ_HM_QUERY_REMARK' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_query_remark') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then NOTE_TEXT end) as NOTE_TEXT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then FOLLOW_UP_REQUIRED_INDICATOR end) as FOLLOW_UP_REQUIRED_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when NOTE_TEXT is not null or FOLLOW_UP_REQUIRED_INDICATOR is not null
                     then md5(upper(coalesce(cast(NOTE_TEXT as varchar), '') || '|' || coalesce(cast(FOLLOW_UP_REQUIRED_INDICATOR as varchar), '')))
                end as SAT_CLAIM_NOTE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_NOTE_HASHDIFF is not null
